def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = ((-1, 0), (1, 0), (0, -1), (0, 1)) # up, down, left, right
    path = []

    def dfs(r, c, visited):
        if (r, c) == goal:
            return True # goal reached

        visited.add((r, c)) # mark current cell as visited
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == '.':
                path.append((nr, nc)) # add neighbor to path
                if dfs(nr, nc, visited): # recursively try to find a path
                    return True
                path.pop() # backtrack if no path found
        visited.remove((r, c)) # unmark current cell as visited
        return False # no path found from current cell

    if dfs(*start, set([start])): # try to find a path from start cell
        return path
    return [] # goal not reachable

