def solve(grid, start, goal):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    grid_dict = {}
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == '.':
                grid_dict[r, c] = True
            else:
                grid_dict[r, c] = False
    queue = deque([(start, [start])])
    visited = set([start])
    while queue:
        current, path = queue.popleft()
        if current == goal:
            return path
