        row, col = pos // C, pos % C
        for drow, dcol in ((0, -1), (-1, 0), (0, 1), (1, 0)):
            neighbour = row + drow, col + dcol
            if (
                0 <= neighbour[0] < R
                and 0 <= neighbour[1] < C
                and board[neighbour[0] * C + neighbour[1]] != " "
            ):
                yield board, neighbour

