            # choose unvisited with lowest path_cost
            u = min((pos, len) for (pos, len) in enumerate(path_len) if not visited)[0]
            visited[u] = True
            # collect neighbors
            for board, (x, y) in neighbors(grid, u):
                v = x * C + y
                if not visited[v]:
                    alt = path_len[u] + cost[v]
                    if alt < path_len[v]:
                        predecessor[v] = u
                        path_len[v] = alt

