class PriorityQueue:
    def __init__(self):
        """Create an empty int-priority queue"""
        self.items = []
​
    def is_empty(self):
        return len(self.items) == 0
​
    def len(self):
        return len(self.items)
​
    def add(self, element):
        """Inserting an element"""
        self.items.append(element)
​
    def minimum(self):
        minimum_priority = float("inf")
        minimum_item = None
        for item in self.items:
            if item.priority < minimum_priority:
                minimum_priority = item.priority
                minimum_item = item
        return minimum_item
​
    def remove_min(self):
        """removing the minimum element in queue"""
        if self.len() == 0:
            return (None, None)
        min_node = self.minimum()
        self.items.remove(min_node)
        return min_node.item, min_node.priority
