def solve(grid, start, goal):
    from collections import deque

    # Check if start or goal is out of bounds or a wall
    if (start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]) or grid[start[0]][start[1]] == '#'):
        return []
    if (goal[0] < 0 or goal[0] >= len(grid) or goal[1] < 0 or goal[1] >= len(grid[0]) or grid[goal[0]][goal[1]] == '#'):
        return []

    # Directions for moving up, down, left, and right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Create a queue for BFS and a set for visited cells
    queue = deque()
    queue.append((start, [start]))
    visited = set()
    visited.add(start)

    while queue:
        current = queue.popleft()
        point = current[0]
        path = current[1]
        # Check if we reached the goal
        if point == goal:
            return path
        # Explore neighbors
        for direction in directions:
            new_row = point[0] + direction[0]
            new_col = point[1] + direction[1]
            new_point = (new_row, new_col)
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and grid[new_row][new_col] != "#" and new_point not in visited:
                queue.append((new_point, path + [new_point]))
                visited.add(new_point)

    return []
