def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])
    dp = [[float('inf')] * cols for _ in range(rows)]

    def dfs(r, c, distance):
        if r < 0 or c < 0 or r >= rows or (c >= cols) or (grid[r][c] == '#'):
            return
        if r == goal[0] and c == goal[1]:
            dp[r][c] = distance
            return
        if r == start[0] and c == start[1]:
            dp[r][c] = distance
            return
        if dp[r][c] != float('inf'):
            return
        dp[r][c] = distance
        dfs(r, c - 1, distance + 1)
        dfs(r, c + 1, distance + 1)
        dfs(r - 1, c, distance + 1)
        dfs(r + 1, c, distance + 1)
    dfs(start[0], start[1], 0)
    path = [goal]
    while path[-1] != start:
        r, c = path[-1]
        min_distance = float('inf')
        min_direction = None
        for dr, dc in [(0, -1), (0, 1), (-1, 0), (1, 0)]:
            nr, nc = (r + dr, c + dc)
            if 0 <= nr < rows and 0 <= nc < cols and (dp[nr][nc] + 1 < min_distance):
                min_distance = dp[nr][nc] + 1
                min_direction = (r - nr, c - nc)
        if min_direction is None:
            return []
        else:
            path.append((r - min_direction[0], c - min_direction[1]))
    return path[::-1]

