    """
    Solve the maze using BFS.
    """
    queue = [([start], {start})]
    while queue:
        path, visited = queue.pop(0)
        if not len(path) == 1 or path[-1] == goal:
            for i, path in route(grid, path, visited):
                if grid[goal[0]][goal[1]] == '.':
                    queue.append([i[:-1], i])
                if not len(i) == len(path):
