        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            tr, tc = (r + dr, c + dc)
            if 0 <= tr < len(grid) and 0 <= tc < len(grid[0]) and (grid[tr][tc] == '.') and ((tr, tc) not in visited):
                return [(tr, tc)]
        return []

    def backtrack(path):
        pr, pc = path[-1]
        options = open_options(pr, pc)
        if options == [] or path == []:
            return path
        for op in options:
            if op == goal:
                return path + [goal]
            if max_depth is not None:
                result = backtrack(path + [op], max_depth - 1)
            else:
                result = backtrack(path + [op])
                if result:
                    return result
            if result:
                return result
        return []
    return backtrack(visited)

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    n, m = (len(grid), len(grid[0]))

    def is_in_board(r: int, c: int, n: int, m: int) -> bool:
        return r >= 0 and c >= 0 and (r < n) and (c < m)

    def is_free(grid: list[str], r: int, c: int) -> bool:
        return grid[r][c] == '.'

    def swap(tuples):
        return (tuples[1], tuples[0])
    from_data = [-1 for _ in range(n * m)]
    from_data[swap(start)] = -1
    queue = [swap(start)]
    grid[start[0]] = grid[start[0]][:start[1]] + '|' + grid[start[0]][start[1] + 1:]
    while queue:
        u = queue.pop(0)
        r = u[0]
        c = u[1]
        for dr, dc in directions:
            r_n = r + dr
            c_n = c + dc
            if is_in_board(r_n, c_n, n, m) and is_free(grid, r_n, c_n):
                from_data[swap((r_n, c_n))] = swap((r, c))
                queue.append(swap((r_n, c_n)))
                if r_n == goal[0] and c_n == goal[1]:
                    grid[r_n] = grid[r_n][:c_n] + '#' + grid[r_n][c_n + 1:]
                    while r_n != start[0] or c_n != start[1]:
