    solution_path = []
    frontier = set([start])
    explored = set([])
    prev = dict([start, None])
    while frontier:
        node = min(frontier, key=lambda node: len(prev[node] if node in prev else []))
        explored.add(node)
        if node == goal:
            goal_node = node
            break
        frontier.remove(node)
        neighbors = set()
        for drow, dcol in i_neigh:
            neighbors.add((node[0] + drow, node[1] + dcol))
        neighbors = valid_neighbor(node, neighbors)
        for neigh in neighbors:
            if neigh not in explored and neigh not in frontier:
                frontier.add(neigh)
                prev[neigh] = node
    while goal_node:
        goal_node, prev_node = (prev[goal_node], prev[prev_node])
        solution_path.append(prev_node)
    solution_path.extend([start])
    return solution_path

