    grid = [list(row) for row in grid]
    grid[start[0]][start[1]] = 'S'
    grid[goal[0]][goal[1]] = 'G'
    grid_set = {(j, i) for i, row in enumerate(grid) for j, elem in enumerate(row) if elem != '#'}
    path = []
