        current_cell = heappop(distances)
        neighbors = [tuple(coord) for coord in [(current_cell[0] - 1, current_cell[1]), (current_cell[0] + 1, current_cell[1])] if coord in grid_set and perm(coord) not in path]
        if neighbors:
            path += perm(neighbors)
        distances.update(neighbors)
        if len(distances) != len(path):
            distances = distances.split(path[-1])
    return path

