    def neighbors(row: int, col: int) -> list:
        possible_neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]
        if row - 1 < 0 or row + 1 > grid_height - 1 or col - 1 < 0 or (col + 1 > grid_width - 1):
            return possible_neighbors
        for position in possible_neighbors:
            if position in visited and visited[position] == PATH:
                print('visited_list_inside_validate_path  : ', visited)
                return position
        return []

    def is_start_goal_in_grid(start: tuple[int, int], goal: tuple[int, int]) -> bool:
        if start[0] < 0 or start[1] < 0 or start[0] > grid_height - 1 or (start[1] > grid_width - 1) or (goal[0] < 0) or (goal[1] < 0) or (goal[0] > grid_height - 1) or (goal[1] > grid_width - 1):
            return False
        return True
    if not is_start_goal_in_grid(start, goal):
        return 'start and goal should be out of grid'
    queue = [{'row': start[0], 'col': start[1], 'path': [start]}]
    visited = {}
    found_goal = False
    while queue:
        node = queue.pop(0)
        current_path = node['path']
        if node['row'] == goal[0] and node['col'] == goal[1]:
            found_goal = True
            return {'current_path': current_path, 'visited': visited, 'found_goal': found_goal}
        if (node['row'], node['col']) in visited:
            continue
        visited[node['row'], node['col']] = PATH
        for neighbor in neighbors(node['row'], node['col']):
            queue.append({'row': neighbor[0], 'col': neighbor[1], 'path': current_path + [neighbor]})
    return {'current_path': [], 'visited': visited, 'found_goal': found_goal}

