def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    queue = [[start]]
    rows, cols = (len(grid), len(grid[0]))
    while queue:
        path = queue.pop(0)
        row, col = path[-1]
        if grid[row][col] == '#':
            continue
        if (row, col) == goal:
            return path
        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]
        for n in neighbors:
            r, c = n
            if r > -1 and r < rows and (c > -1) and (c < cols) and (grid[r][c] == '.'):
                new_path = list(path)
                new_path.append((r, c))
                queue.append(new_path)

