# helper function that returns the valid neighbours of a given (row, col)
def valid_neighbours(graph: dict[int, dict[int, str]], state: (int, int)) -> ((int, int)):
    """
    Takes a graph and the current (row, col) coordinates.

    Returns a list of tuples containing the valid neighbour (row, col) coordinates of a given state.
    """
    x,y = state
    validneighbours = []
    try: # right
        if graph[state[0]][state[1]+1] != "#":
            validneighbours.append((state[0], state[1]+1))
    except KeyError:
        pass

    try: # left
        if graph[state[0]][state[1]-1] != "#":
            validneighbours.append((state[0], state[1]-1))
    except KeyError:
        pass

    try: # up
        if graph[state[0]+1][state[1]] != "#":
            validneighbours.append((state[0]+1, state[1]))
    except KeyError:
        pass

    try: # down
        if graph[state[0]-1][state[1]] != "#":
            validneighbours.append((state[0]-1, state[1]))
    except KeyError:
