        visited_cells.add(current_cell)
        for direction in directions:
            row = current_cell[0] + direction[0]
            col = current_cell[1] + direction[1]
            if (row, col) not in visited_cells and row >= 0 and (col >= 0):
                cell = (row, col)
                if row < 0 or col < 0 or col >= col_length:
                    continue
                if len(grid[row]) > col:
                    cell_value = grid[row][col]
                    if cell_value == '.':
                        queue.append(current_path + [cell])
                if cell == goal:
                    return current_path + [cell]
    return []

