    if start == goal:
        return [start]

    def traverse(i, j):
        if (i, j) == goal:
            return [(i, j)]
        traverse.queue.append((i, j))
        for r, c in [(i, j - 1), (i, j + 1), (i + 1, j), (i - 1, j)]:
            if len(grid) - 1 >= r >= 0 and len(grid[0]) - 1 >= c >= 0 and (grid[r][c] == '.') and ((r, c) not in traverse.last_r_c_set):
                traverse.last_r_c_set.add((r, c))
                traverse.queue.append((r, c))
                if traverse.dist[r, c] > traverse.dist[i, j] + 1:
                    traverse.dist[r, c] = traverse.dist[i, j] + 1
                    traverse.after[r, c] = [(i, j)]
                else:
                    traverse.after[r, c] += [(i, j)]
        while len(traverse.last_r_c_set) < len(traverse.queue) and (r, c) != start:
            r, c = traverse.queue.pop(0)
        if (r, c) == start:
            traverse.queue = []
        traverse.last_r_c_set = set()
    traverse.dist = {(i, j): 999999 for i in range(len(grid)) for j in range(len(grid[0]))}
    traverse.dist[start] = 0
    traverse.after = dict.fromkeys(list(traverse.dist), [])
    traverse.after[start] = [(0, 0)]
    traverse.last_r_c_set, traverse.queue = (set(), [start])
    while traverse.queue:
        i, j = traverse.queue.pop(0)
        traverse(i, j)
    if goal not in traverse.after:
        return []
    return [start] + traverse.after[goal][::-1] + [goal]

