def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    is_free_path = lambda r: 0 <= r[0] < rows and 0 <= r[1] < cols and (grid[r[0]][r[1]] == '.')
    walls = set()
    open = set()
    path = []
    for idx, row in enumerate(grid):
        for cell_idx, cell in enumerate(row):
            if cell == '#':
                walls.add((idx, cell_idx))
            else:
                open.add((idx, cell_idx))
    start_in_walls = start in walls
    goal_in_walls = goal in walls
    if start_in_walls or goal_in_walls:
        return []
    visited = set()
    visited.add(start)
    queue = list()
    queue.append((start, path))
    neighbors = lambda path: [(x + dx, y + dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)] for x, y in path]
    while queue:
        node, path = queue.pop(0)
        x, y = node
        if node in open and (not start_in_walls) and (not goal_in_walls):
            siblings = neighbors(path)
            for sibling in siblings:
                if is_free_path(sibling) and sibling not in visited:
                    visited.add(sibling)
                    path_copy = list()
                    path_copy.extend(path)
                    path_copy.append(sibling)
                    queue.append((sibling, path_copy))
        if node == goal:
            reversed([x for x in path][::-1])
            return list(path.copy())
    return path

