            if grid[r - 1][c] == '#' and grid[r + 1][c] == '#' and (grid[r][c - 1] == '#') and (grid[r][c + 1] == '#'):
                raise ValueError(f'No possible moves inside at ({r}, {c})')
    solutions = []

