            if 0 <= n_r < row and 0 <= n_c < col and (grid[n_r][n_c] == '.'):
                yield (n_r, n_c)

    def solve_helper(path):
        r_path, c_path = path[:-1]
        if grid[r_path][c_path] == '.':
            for r, c in valid_neighbor(r_path, c_path):
