def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    if grid[start][0] == '#' or grid[start][len(grid[start]) - 1] == '#':
        return []
    queue = [(0, start)]
    depth = len(grid) - 1
    while queue:
        path, (row, col) = queue.pop()
        if grid[row][col] == 'G':
            return [p for p, _ in path]
        if row < 0 or row > depth or col < 0 or (col > len(grid[row]) - 1) or (grid[row][col] == '#'):
            continue
        for c in set(path):
            grid[c[0]][c[1]] = '#'
        queue.append((path + [(row, col)], (row - 1, col)))
        queue.append((path + [(row, col)], (row, col + 1)))
        queue.append((path + [(row, col)], (row + 1, col)))
        queue.append((path + [(row, col)], (row, col - 1)))
    return []

