                        dist[nr][nc] = dist[r][c] + 1
                        prev[nr][nc] = (r, c)
    if dist[goal[0]][goal[1]] == float('inf'):
        return []
    current = goal
    while current:
        path.append(current)
        r, c = current
        current = prev[r][c]
        if current == start:
            path.append(start)
            break
        if not current:
            break
    return path

