from heapq import heappop, heappush

def solve(n, edges, s, t):
    # Initialize distance to infinity for all nodes except the starting node
    distances = [float('inf')] * n
    distances[s] = 0

    # Create a list of edges for each node
    adjacency_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adjacency_list[u].append((v, w))

    # Priority queue to process nodes in order of their minimum distance from s
    pq = [(0, s)]  # (distance, node)

    while pq:
        dist, node = heappop(pq)

        # If the current distance is greater than the known shortest distance, skip
        if dist > distances[node]:
            continue

        # If we reach the target node, return the distance
        if node == t:
            return dist

        # Explore neighbors
        for neighbor, weight in adjacency_list[node]:
            new_dist = dist + weight

            # If a shorter path is found, update the distance and push to the pq
            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heappush(pq, (new_dist, neighbor))

    # If t is unreachable from s
    return -1
