def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    """
    The shortest path from s to t (bfs).
    :param n: number of nodes (0...n-1)
    :param edges: edges list
    :return: distance from s to t in graph or -1
    """
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append({'to': v, 'weight': w})
    visited = set()
    q = [(s, 0)]
    while q:
        node, dist = q.pop(0)
        if node == t:
            return dist
        if node not in visited:
            visited.add(node)
            for neighbour in graph[node]:
                q.append((neighbour['to'], neighbour['weight'] + dist))
    return -1

