    g = {node: set() for node in range(n)}
    q: list[int] = []
    weights: dict[int, int] = {node: -1 for node in range(n)}
    for e in edges:
        g[e[0]].add((e[1], e[2]))
    weights[s] = 0
    q.append(s)
    while q:
        cur = q.pop(0)
        for e in g[cur]:
