    adjacency: defaultdict[int, list[tuple[int, int]]] = defaultdict(list)
    stime = time.perf_counter()
    for edge in edges:
        from_node, to_node, weight = edge
        adjacency[from_node].append((to_node, weight))
    source_dist = {s: 0}
    source_priority = [(0, s)]
    shortest_paths: dict[int, list[list[int]]] = {source: [[s]]}
    destination_found = False
