def BellmanFord(n: int, edges: list[tuple[int, int, int]], s: int):
    """Bellman-Ford Algorithm"""
    distances = {node: float("inf") for node in range(n)}
    distances[s] = 0

    """Check for shortest path"""
    for i in range(n-1):
        distances = alt_fun(distances, edges)

    """Check for negative cycles"""
    best_found = False
    for [u, v, w] in edges:
        if distances[v] > distances[u] + w:
            best_found = True
        if best_found:
            return None

    return distances[t]

def alt_fun(distances: dict, edges: list[tuple[int, int, int]]) -> dict:
    """One relaxation iteration, return new distances"""
    new_distances: dict = {}
    for v in distances:
        new_distances[v] = distances[v]
    for [u,v,w] in edges:
        new_distances[v] = min(new_distances[v], distances[u] + w)
    return new_distances

